// SetFlowFilter sets a FlowFilter field's filter expression (SETFILTER on a
// FlowFilter field); FlowFields applying it use it from then on. "" clears it.
func (t *ProjectBudgetLine) SetFlowFilter(field, expr string) error {
	switch field {
	case "date_filter":
		if err := flowfilter.Validate(flowfilter.KindDate, expr); err != nil {
			return err
		}
		t.Date_filter = expr
		return nil
	}
	return fmt.Errorf("%q is not a FlowFilter field of Project_Budget_Line", field)
}

// FlowFilterExpressions returns the FlowFilters set (SetFlowFilter), so they can go along with
// the record's filters (a page opened with SetTableView shows them)
func (t *ProjectBudgetLine) FlowFilterExpressions() []tables.FieldFilter {
	var result []tables.FieldFilter
	if t.Date_filter != "" {
		result = append(result, tables.FieldFilter{Field: "date_filter", Expression: t.Date_filter})
	}
	return result
}

